python3 -c "
with open('/app/samples/s06_empty.jrn', 'rb') as f:
    b = f.read()

payload = b[:-4]
exp_be = int.from_bytes(b[-4:], 'big')
exp_le = int.from_bytes(b[-4:], 'little')

# Let's test standard CRC32 with various poly, init, xorout, refin, refout
def make_crc(poly, init, xorout, refin, refout):
    def reflect(n, bits):
        res = 0
        for _ in range(bits):
            res = (res << 1) | (n & 1)
            n >>= 1
        return res

    # Table-less calculation
    crc = init
    for byte in payload:
        if refin:
            byte = reflect(byte, 8)
        crc ^= (byte << 24)
        for _ in range(8):
            if crc & 0x80000000:
                crc = ((crc << 1) ^ poly) & 0xFFFFFFFF
            else:
                crc = (crc << 1) & 0xFFFFFFFF
    if refout:
        crc = reflect(crc, 32)
    crc ^= xorout
    return crc

polys = [0x04C11DB7, 0x1EDC6F41, 0xA833982B, 0x814141AB, 0x000000af]
inits = [0x00000000, 0xFFFFFFFF]
xorouts = [0x00000000, 0xFFFFFFFF]

found = False
for poly in polys:
    for init in inits:
        for xorout in xorouts:
            for refin in [False, True]:
                for refout in [False, True]:
                    c = make_crc(poly, init, xorout, refin, refout)
                    if c == exp_be or c == exp_le:
                        print(f'Match! poly={hex(poly)}, init={hex(init)}, xorout={hex(xorout)}, refin={refin}, refout={refout}')
                        found = True
if not found:
    print('No standard CRC32 matched')
"

