import glob, hashlib, zlib

payload = open('/app/samples/s06_empty.jrn', 'rb').read()[:-4]
exp = open('/app/samples/s06_empty.jrn', 'rb').read()[-4:]

for name in hashlib.algorithms_available:
    try:
        h = hashlib.new(name, payload).digest()
        if h[:4] == exp:
            print('Match prefix 4:', name)
        if h[-4:] == exp:
            print('Match suffix 4:', name)
        if h[:4] == exp[::-1]:
            print('Match prefix 4 rev:', name)
        if h[-4:] == exp[::-1]:
            print('Match suffix 4 rev:', name)
    except Exception:
        pass
"

